  const [name, setName] = useState('');

  const handleInputChange = (event) => {
    // Sanitize user input before updating state
    setName(event.target.value.replace(/<|>|/g, ''));
  };

  return <input type="text" onChange={handleInputChange} value={name} />;
};
```
